(async()=>{const out={};for(const kind of ['audio','video'])for(const direction of ['sendrecv','recvonly','sendonly','inactive','legacy']){const p=new RTCPeerConnection();if(direction!=='legacy')p.addTransceiver(kind,{direction});const options=direction==='legacy'?{[kind==='audio'?'offerToReceiveAudio':'offerToReceiveVideo']:true}:{};const d=await p.createOffer(options);out[kind+'|'+direction]=d.sdp.split('\r\n').filter(s=>/^(m=|a=(extmap:|rtpmap:|fmtp:|rtcp-fb:|rtcp-xr:))/.test(s));p.close()}return out})()
